const operations = {
  'plus': (a, b) => a + b,
  'minus': (a, b) => a - b,
  'multiplied by': (a, b) => a * b,
  'divided by': (a, b) => Math.floor(a / b)
};

const parseQuestion = (question: string): [number, string, number][] => {
  const regex = /What is (\d+) (plus|minus|multiplied by|divided by) (\d+)/g;
  const matches = [];
  let match;
  while ((match = regex.exec(question)) !== null) {
    matches.push([Number(match[1]), match[2], Number(match[3])]);
  }
  return matches;
};

const answer: AnswerFn = (question: string): number => {
  const parsed = parseQuestion(question);
  if (parsed.length === 0) {
    throw new Error('Invalid syntax');
  }
  let result = parsed[0][0];
  for (let i = 0; i < parsed.length; i++) {
    const [a, op, b] = parsed[i];
    if (!operations[op]) {
      throw new Error('Unsupported operation');
    }
    result = operations[op](result, b);
  }
  return result;
};

